import { candidatesFor } from '@/server/utils/embed'
import { fold } from '@/server/utils/text'

// Every guessable word of a language (dictionary words and forms + proper nouns), generated by scripts/build-lexicon.mjs
// into Nitro server assets. Loaded once per instance; validating a guess never touches the network.
type ByFold = Map<string, string | string[]> // a single spelling is stored as a plain string to save memory
const lexicons = new Map<string, Promise<ByFold>>()

async function load(lang: string): Promise<ByFold> {
  const raw = await useStorage('assets:server').getItemRaw(`lexicon-${lang}.txt`)
  const text = raw == null ? '' : typeof raw === 'string' ? raw : Buffer.from(raw as Uint8Array).toString('utf8')
  const map: ByFold = new Map()
  for (const w of text.split('\n')) {
    if (!w) continue
    const f = fold(w)
    const hit = map.get(f)
    if (hit === undefined) map.set(f, w)
    else map.set(f, typeof hit === 'string' ? [hit, w] : [...hit, w])
  }
  return map
}

const MAX_SPELLINGS = 3

/**
 * Dictionary spellings a typed word stands for ("incarcerees" -> ["incarcérées"]): the word itself when it is valid,
 * else spellings already embedded, else the lexicon's accent variants. Empty when the word doesn't exist.
 */
export async function findSpellings(lang: string, typed: string): Promise<string[]> {
  const f = fold(typed)
  const known = await candidatesFor(f, lang)
  if (known.length) return known

  let lex = lexicons.get(lang)
  if (!lex) lexicons.set(lang, (lex = load(lang)))
  const hit = (await lex).get(f)
  if (hit === undefined) return []
  const all = typeof hit === 'string' ? [hit] : hit
  return all.includes(typed) ? [typed] : all.slice(0, MAX_SPELLINGS)
}
